/**
 * @description End-to-end tests with records for sharing, the schedule, clean-up and Monitor retry. Date maths, the
 * Monitor period and share names are covered without data in IntegrationHubUnitTest.
 */
@IsTest
private class IntegrationHubOpsTest {

    @TestSetup
    static void setup() {
        IntegrationHubTestData.setupAll();
    }

    @IsTest
    static void sharingCopiesRelatedAccess() {
        User reader = IntegrationHubTestData.reader();
        Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(200, '{}'));
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Event__c related = new IH_Event__c(Name = 'Shared', Event_Key__c = 'SHARED_RECORD', Direction__c = 'Outbound');
            IH_Event__c ev = new IH_Event__c(Name = 'Share test', Event_Key__c = 'EVENT_OUT', Direction__c = 'Outbound', Active__c = true,
                Related_Object__c = 'IH_Event__c', Path__c = '/share', Share_With_Related_Record__c = true,
                Connection__c = IntegrationHubTestData.eventByKey(IntegrationHubTestData.OUT_KEY).Connection__c);
            IntegrationHubData.insertAll(new List<IH_Event__c>{ related, ev });
            IH_Event__Share manual = new IH_Event__Share(ParentId = related.Id, UserOrGroupId = reader.Id, AccessLevel = 'Read');
            IntegrationHubData.insertAll(new List<IH_Event__Share>{ manual });
            List<Id> txnIds = IntegrationHub.publish('EVENT_OUT', new List<Id>{ related.Id });
            Assert.areEqual(1, [SELECT COUNT() FROM IH_Transaction__Share WHERE ParentId = :txnIds[0] AND UserOrGroupId = :reader.Id
                AND RowCause = :Schema.IH_Transaction__Share.RowCause.Related_Record_Access__c WITH SYSTEM_MODE],
                'the reader gets Read on the transaction');
            try {
                IntegrationHubData.deleteAll(new List<IH_Event__Share>{ manual });
            } catch (DmlException e) {
                Assert.isNotNull(e.getMessage(), 'delete skipped');
            }
            IntegrationHub.syncSharing(new Set<Id>{ related.Id });
            Assert.areEqual(0, [SELECT COUNT() FROM IH_Transaction__Share WHERE ParentId = :txnIds[0] AND UserOrGroupId = :reader.Id
                AND RowCause = :Schema.IH_Transaction__Share.RowCause.Related_Record_Access__c WITH SYSTEM_MODE],
                'removed access is removed on resync');
            IntegrationHub.syncSharing(null);
        }
    }

    @IsTest
    static void scheduleAllIsIdempotent() {
        System.runAs(IntegrationHubTestData.admin()) {
            String name = IntegrationHubMaintenance.CLEANUP_JOB;
            Integer before = [SELECT COUNT() FROM CronTrigger WHERE CronJobDetail.Name = :name WITH SYSTEM_MODE];
            Test.startTest();
            IntegrationHubMaintenance.scheduleAll();
            Integer afterFirst = [SELECT COUNT() FROM CronTrigger WHERE CronJobDetail.Name = :name WITH SYSTEM_MODE];
            IntegrationHubMaintenance.scheduleAll();
            Test.stopTest();
            Assert.areEqual(1, afterFirst, 'exactly one clean-up job is scheduled');
            Assert.isTrue(IntegrationHubMaintenance.isScheduled(), 'the job is reported as scheduled');
            Assert.isTrue(before <= 1, 'there was at most one clean-up job before');
            Assert.areEqual(afterFirst, [SELECT COUNT() FROM CronTrigger WHERE CronJobDetail.Name = :name WITH SYSTEM_MODE],
                'a second run schedules nothing');
        }
    }

    @IsTest
    static void cleanupDeletesOldAndTimesOutCallbacks() {
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Transaction__c done = IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Success');
            IH_Transaction__c waiting = IntegrationHubTestData.newTransaction(IntegrationHubTestData.CALLBACK_KEY, 'Sent');
            IntegrationHubData.updateAll(new List<IH_Transaction__c>{
                new IH_Transaction__c(Id = done.Id, Completed_At__c = System.now().addDays(-100)),
                new IH_Transaction__c(Id = waiting.Id, Last_Attempt__c = System.now().addHours(-30)) });
            Test.startTest();
            new IntegrationHubMaintenance(IntegrationHubMaintenance.CLEANUP, null, null).execute((SchedulableContext) null);
            Test.stopTest();
            Assert.areEqual(0, IntegrationHubTestData.transactions(IntegrationHubTestData.OUT_KEY).size(), 'old Success is deleted');
            IH_Transaction__c late = IntegrationHubTestData.transactions(IntegrationHubTestData.CALLBACK_KEY)[0];
            Assert.areEqual('Failed', late.Status__c, 'no callback in time is Failed');
            IH_Settings__c result = IH_Settings__c.getOrgDefaults();
            Assert.isNotNull(result.Last_Cleanup_At__c, 'the run time is saved');
            Assert.areEqual(1, result.Last_Cleanup_Deleted__c, 'the deleted count is saved');
            Assert.areEqual(1, result.Last_Cleanup_Timed_Out__c, 'the timed-out count is saved');
        }
    }

    @IsTest
    static void monitorRetryInBackground() {
        System.runAs(IntegrationHubTestData.admin()) {
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(200, '{}'));
            Test.startTest();
            // Records are created after startTest: a callout in a job that runs at stopTest fails if DML came before startTest.
            IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Failed');
            IntegrationHubMaintenance.retryInBackground('Status__c IN :bad', new Map<String, Object>{
                'bad' => IntegrationHubMaintenance.badStatuses() });
            Test.stopTest();
            String status = IntegrationHubTestData.transactions(IntegrationHubTestData.OUT_KEY)[0].Status__c;
            Assert.isTrue(status == 'Retry' || status == 'Success', 'the failure was marked for retry or sent: ' + status);
        }
    }

    @IsTest
    static void monitorSummaryAndRetry() {
        Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(200, '{}'));
        System.runAs(IntegrationHubTestData.reader()) {
            try {
                IntegrationHubMonitorController.getSummary(null, null);
                Assert.fail('a reader must not see the Monitor');
            } catch (AuraHandledException e) {
                Assert.isTrue(e.getMessage().contains('Admin'), 'the error names the permission');
            }
        }
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Transaction__c one = IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Failed');
            IH_Transaction__c two = IntegrationHubTestData.newTransaction(IntegrationHubTestData.CALLBACK_KEY, 'Abandoned');
            IntegrationHubMonitorController.Summary s = IntegrationHubMonitorController.getSummary(System.today().addDays(-1), null);
            Assert.isFalse(s.counts.isEmpty(), 'totals are returned');
            Assert.areEqual(2, s.groups.size(), 'one group per event and error');
            Assert.areEqual(2, s.groupedFrom, 'both failures were grouped');
            Assert.isFalse(s.groupsSampled, 'all failures fit in the sample');
            IntegrationHubMonitorController.GroupRequest grp = new IntegrationHubMonitorController.GroupRequest();
            grp.eventName = IntegrationHubTestData.OUT_KEY;
            grp.errorSummary = 'HTTP 500';
            Assert.areEqual(1, IntegrationHubMonitorController.retryGroup(grp),
                'the group is retried');
            Assert.areEqual(1, IntegrationHubMonitorController.retryIds(new List<Id>{ two.Id, one.Id }), 'only failed ones are retried');
            Assert.areEqual(0, IntegrationHubMonitorController.retryIds(null), 'nothing chosen');
            Assert.areEqual('Retry', IntegrationHubTestData.transactions(IntegrationHubTestData.OUT_KEY)[0].Status__c,
                'the transaction waits for the send');
        }
    }

    @IsTest
    static void checkConnectionReportsWhatHappened() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Connection__c c = new IH_Connection__c(Name = 'Check me', Named_Credential__c = 'IH_Check', Active__c = true);
            IH_Connection__c blank = new IH_Connection__c(Name = 'No credential');
            IntegrationHubData.insertAll(new List<IH_Connection__c>{ c, blank });
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(404, 'not here'));
            Test.startTest();
            IntegrationHubEndpointCheck.CheckResult ok = IntegrationHubEndpointCheck.checkConnection(c.Id);
            IntegrationHubEndpointCheck.CheckResult none = IntegrationHubEndpointCheck.checkConnection(blank.Id);
            Test.stopTest();
            Assert.isTrue(ok.reached, 'any HTTP answer means the system was reached');
            Assert.areEqual(404, ok.statusCode, 'the status is returned');
            Assert.isFalse(none.reached, 'no Named Credential, no call');
            Assert.isTrue(IntegrationHubEndpointCheck.checkMessage(401).contains('credential'), '401 points at the credential');
        }
    }

    @IsTest
    static void checkEventCallsItsPath() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Connection__c c = new IH_Connection__c(Name = 'Event check', Named_Credential__c = 'IH_Check', Active__c = true);
            IntegrationHubData.insertAll(new List<IH_Connection__c>{ c });
            IH_Event__c withPath = new IH_Event__c(Name = 'With path', Event_Key__c = 'IH_CHECK_PATH', Direction__c = 'Outbound',
                Connection__c = c.Id, Related_Object__c = 'Account', Path__c = '/api/v1/items/{recordId}', Http_Method__c = 'POST');
            IH_Event__c noPath = new IH_Event__c(Name = 'No path', Event_Key__c = 'IH_CHECK_NOPATH', Direction__c = 'Outbound',
                Connection__c = c.Id, Related_Object__c = 'Account');
            IntegrationHubData.insertAll(new List<IH_Event__c>{ withPath, noPath });
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(405, 'method not allowed'));
            Test.startTest();
            IntegrationHubEndpointCheck.CheckResult found = IntegrationHubEndpointCheck.checkEvent(withPath.Id);
            IntegrationHubEndpointCheck.CheckResult missing = IntegrationHubEndpointCheck.checkEvent(noPath.Id);
            Test.stopTest();
            Assert.isTrue(found.reached, 'the endpoint was called');
            Assert.isTrue(found.message.startsWith('Endpoint found'), '405 means the endpoint exists');
            Assert.areEqual('method not allowed', found.reply, 'the start of the reply is returned');
            Assert.isNull(IntegrationHubEndpointCheck.replyStart(' '), 'no body gives no reply');
            Assert.isFalse(missing.reached, 'no Path, no call');
            Assert.areEqual('This event has no Path.', missing.message, 'the missing Path is named');
        }
    }

    @IsTest
    static void eventCheckExplainsEachCase() {
        System.runAs(IntegrationHubTestData.admin()) {
            Assert.areEqual('Event not found.', IntegrationHubEndpointCheck.eventProblem(null), 'no event');
            Assert.isTrue(IntegrationHubEndpointCheck.eventProblem(new IH_Event__c(Direction__c = 'Inbound'))
                .startsWith('Inbound'), 'inbound is not checked');
            Assert.isTrue(IntegrationHubEndpointCheck.eventProblem(new IH_Event__c(Direction__c = 'Outbound'))
                .contains('no Connection'), 'a Connection is needed');
            Assert.isTrue(IntegrationHubEndpointCheck.eventMessage(404, 'POST').contains('404'), '404 points at the Path');
            Assert.isTrue(IntegrationHubEndpointCheck.eventMessage(405, null).contains('POST'), '405 is expected for POST');
            Assert.isTrue(IntegrationHubEndpointCheck.eventMessage(403, 'POST').contains('credential'), '403 points at the credential');
            Assert.isTrue(IntegrationHubEndpointCheck.eventMessage(200, 'POST').startsWith('Reached'), 'other answers are shown');
        }
    }

    @IsTest
    static void checkConnectionNotReached() {
        IntegrationHubMonitorController.adminInTest = true;
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Connection__c c = new IH_Connection__c(Name = 'Down', Named_Credential__c = 'IH_Down', Active__c = true);
            IntegrationHubData.insertAll(new List<IH_Connection__c>{ c });
            Test.setMock(HttpCalloutMock.class, new IntegrationHubTestData.Mock(0, ''));
            Test.startTest();
            IntegrationHubEndpointCheck.CheckResult r = IntegrationHubEndpointCheck.checkConnection(c.Id);
            Test.stopTest();
            Assert.isFalse(r.reached, 'a callout error means not reached');
            Assert.isTrue(r.message.startsWith('Not reached'), 'the error is explained');
        }
    }
}
